def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    # Check if this is an escaped quote or the closing quote
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Check if followed by comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Quote in unquoted field is malformed
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < n:
                i += 1  # Skip the comma

    return fields

